// Generated by LCD Wizard - filesystem pictures held in memory while their screen shows
//
// LVGL draws a picture from a file by opening it and reading it a row at a
// time on every draw, so a screen that slides judders. Here, when a screen
// starts to load, each Image on it whose picture is a file is given the
// file's pixels in memory - PSRAM first, the chip's own RAM if it has room
// to spare, never LVGL's pool - and LVGL draws them where they are. When the
// screen has gone the path is put back and the memory freed. A picture there
// is no room for is read from the file as before: slower, never missing.

#include "ui_imgmem.h"
#include <stdlib.h>
#include <string.h>

#if LV_USE_IMG

#if defined(ESP_PLATFORM)
#include <esp_heap_caps.h>
#endif

// What is left free after a picture is taken, so the rest of the firmware
// (Wi-Fi, the draw buffers, LVGL's own layers) still has room. Raise them if
// something else runs short while a picture's screen shows.
#define IMGMEM_SPARE_PSRAM     (64U * 1024U)
#define IMGMEM_SPARE_INTERNAL  (32U * 1024U)
#define IMGMEM_CHUNK           (16U * 1024U)

typedef struct im_pic {
    struct im_pic * next;
    lv_obj_t * screen;
    char * path;             // the Image's own path, put back when the screen goes
    lv_img_dsc_t dsc;
    void * px;               // NULL: no room, left on the file
} im_pic;

typedef struct im_use {
    struct im_use * next;
    lv_obj_t * screen;
    lv_obj_t * obj;
    im_pic * pic;
} im_use;

static im_pic * im_pics = NULL;
static im_use * im_uses = NULL;

static void * im_alloc(size_t n)
{
#if defined(ESP_PLATFORM)
    if (heap_caps_get_largest_free_block(MALLOC_CAP_SPIRAM | MALLOC_CAP_8BIT) >= n + IMGMEM_SPARE_PSRAM) {
        void * p = heap_caps_malloc(n, MALLOC_CAP_SPIRAM | MALLOC_CAP_8BIT);
        if (p) return p;
    }
    if (heap_caps_get_largest_free_block(MALLOC_CAP_INTERNAL | MALLOC_CAP_8BIT) >= n + IMGMEM_SPARE_INTERNAL &&
        heap_caps_get_free_size(MALLOC_CAP_INTERNAL | MALLOC_CAP_8BIT) >= n + IMGMEM_SPARE_INTERNAL) {
        return heap_caps_malloc(n, MALLOC_CAP_INTERNAL | MALLOC_CAP_8BIT);
    }
    return NULL;
#else
    return malloc(n);
#endif
}

// The file's header into the descriptor, its pixels into memory of their own.
static void im_load(im_pic * p)
{
    lv_fs_file_t f;
    if (lv_fs_open(&f, p->path, LV_FS_MODE_RD) != LV_FS_RES_OK) return;
    uint32_t size = 0, br = 0;
    if (lv_fs_seek(&f, 0, LV_FS_SEEK_END) != LV_FS_RES_OK || lv_fs_tell(&f, &size) != LV_FS_RES_OK ||
        size <= sizeof(lv_img_header_t) || lv_fs_seek(&f, 0, LV_FS_SEEK_SET) != LV_FS_RES_OK ||
        lv_fs_read(&f, &p->dsc.header, sizeof(lv_img_header_t), &br) != LV_FS_RES_OK || br != sizeof(lv_img_header_t)) {
        lv_fs_close(&f);
        return;
    }
    uint32_t n = size - (uint32_t)sizeof(lv_img_header_t);
    uint8_t * px = (uint8_t *)im_alloc(n);
    if (!px) {
        LV_LOG_INFO("%s: no room for %u bytes, read from the file", p->path, (unsigned)n);
        lv_fs_close(&f);
        return;
    }
    uint32_t got = 0;
    while (got < n) {
        uint32_t want = n - got < IMGMEM_CHUNK ? n - got : IMGMEM_CHUNK;
        if (lv_fs_read(&f, px + got, want, &br) != LV_FS_RES_OK || br == 0) break;
        got += br;
    }
    lv_fs_close(&f);
    if (got != n) { free(px); return; }
    p->dsc.data_size = n;
    p->dsc.data = px;
    p->px = px;
}

static im_pic * im_pic_for(lv_obj_t * screen, const char * path)
{
    for (im_pic * p = im_pics; p; p = p->next) {
        if (p->screen == screen && strcmp(p->path, path) == 0) return p;
    }
    im_pic * p = (im_pic *)calloc(1, sizeof(im_pic));
    if (!p) return NULL;
    p->path = (char *)malloc(strlen(path) + 1);
    if (!p->path) { free(p); return NULL; }
    strcpy(p->path, path);
    p->screen = screen;
    im_load(p);
    p->next = im_pics;
    im_pics = p;
    return p;
}

static void im_forget(lv_obj_t * obj);

// An Image deleted while its screen shows lets go of its picture.
static void im_obj_event(lv_event_t * e)
{
    im_forget(lv_event_get_current_target(e));
}

static void im_forget(lv_obj_t * obj)
{
    for (im_use ** u = &im_uses; *u; ) {
        if ((*u)->obj == obj) { im_use * d = *u; *u = d->next; free(d); }
        else u = &(*u)->next;
    }
}

static void im_take(lv_obj_t * screen, lv_obj_t * obj)
{
    if (lv_obj_check_type(obj, &lv_img_class)) {
        const void * src = lv_img_get_src(obj);
        if (src && lv_img_src_get_type(src) == LV_IMG_SRC_FILE) {
            im_pic * p = im_pic_for(screen, (const char *)src);
            im_use * u = p && p->px ? (im_use *)malloc(sizeof(im_use)) : NULL;
            if (u) {
                u->screen = screen;
                u->obj = obj;
                u->pic = p;
                u->next = im_uses;
                im_uses = u;
                lv_img_set_src(obj, &p->dsc);
                lv_obj_add_event_cb(obj, im_obj_event, LV_EVENT_DELETE, NULL);
            }
        }
    }
    uint32_t n = lv_obj_get_child_cnt(obj);
    for (uint32_t i = 0; i < n; i++) im_take(screen, lv_obj_get_child(obj, (int32_t)i));
}

// The screen has gone (or is going): paths back where the Image still shows
// the copy, then the copies freed.
static void im_release(lv_obj_t * screen, bool put_back)
{
    for (im_use ** u = &im_uses; *u; ) {
        im_use * d = *u;
        if (d->screen != screen) { u = &d->next; continue; }
        *u = d->next;
        if (put_back) {
            lv_obj_remove_event_cb(d->obj, im_obj_event);
            if (lv_img_get_src(d->obj) == &d->pic->dsc) lv_img_set_src(d->obj, d->pic->path);
        }
        free(d);
    }
    for (im_pic ** q = &im_pics; *q; ) {
        im_pic * p = *q;
        if (p->screen != screen) { q = &p->next; continue; }
        *q = p->next;
    lv_img_cache_invalidate_src(&p->dsc);   // LVGL 8 may hold it open
        free(p->px);
        free(p->path);
        free(p);
    }
}

static void im_screen_event(lv_event_t * e)
{
    lv_obj_t * screen = lv_event_get_current_target(e);
    lv_event_code_t code = lv_event_get_code(e);
    if (code == LV_EVENT_SCREEN_LOAD_START) im_take(screen, screen);
    else if (code == LV_EVENT_SCREEN_UNLOADED && screen != lv_scr_act()) im_release(screen, true);
    else if (code == LV_EVENT_DELETE) im_release(screen, false);
}

void ui_imgmem_attach(lv_obj_t * screen)
{
    lv_obj_add_event_cb(screen, im_screen_event, LV_EVENT_SCREEN_LOAD_START, NULL);
    lv_obj_add_event_cb(screen, im_screen_event, LV_EVENT_SCREEN_UNLOADED, NULL);
    lv_obj_add_event_cb(screen, im_screen_event, LV_EVENT_DELETE, NULL);
}

#else

void ui_imgmem_attach(lv_obj_t * screen) { (void)screen; }

#endif
